GLYPHS = DATA['glyphs']
LIGATURES = DATA.get('ligatures', {})

BY_CHAR = DATA['indices']['byChar']
LIGATURES_BY_KEY = DATA['indices'].get('ligaturesByKey', {})
LIGATURES_BY_SEQUENCE = DATA['indices'].get('ligaturesBySequence', {})

def get_glyph_by_char(ch: str):
    key = BY_CHAR.get(ch)
    return GLYPHS.get(key) if key else None

def get_ligature_by_key(key: str):
    seq = LIGATURES_BY_KEY.get(key)
    return LIGATURES.get(seq) if seq else None

def get_ligature_by_sequence(seq_key: str):
    return LIGATURES.get(seq_key)
